          box-shadow: inset 0 0 20px rgba(220, 20, 60, 0.3), inset 0 0 8px rgba(255, 0, 0, 0.4);
        }
      }

      @keyframes danger-breathe {

        0%,
        100% {
          transform: translateY(0);
          box-shadow: 0 0 5px rgba(255, 77, 77, 0.1);
        }

        50% {
          transform: translateY(-4px);
          box-shadow: 0 8px 15px rgba(255, 77, 77, 0.4);
        }
      }

      @keyframes fatal-pulse {

        0%,
        100% {
          transform: scale(1);
          box-shadow: 0 0 15px rgba(255, 0, 0, 0.4), inset 0 0 10px rgba(255, 0, 0, 0.2);
        }

        5% {
          transform: scale(1.02);
          box-shadow: 0 0 35px rgba(255, 0, 0, 0.8), inset 0 0 25px rgba(255, 0, 0, 0.5);
        }

        25% {
          transform: scale(1.01);
          box-shadow: 0 0 25px rgba(255, 0, 0, 0.6), inset 0 0 15px rgba(255, 0, 0, 0.3);
        }
      }

      @keyframes icon-glitch {

        0%,
        100% {
          transform: scale(1);
          filter: drop-shadow(0 0 2px red);
        }

        5% {
          transform: scale(1.3) rotate(-15deg);
          filter: drop-shadow(0 0 15px #ff1a1a);
        }

        15% {
          transform: scale(0.9) rotate(10deg);
        }
      }

      @keyframes tian-glow {

        0%,
        100% {
          border-color: #ffd700;
          box-shadow: 0 0 6px rgba(255, 215, 0, 0.2);
        }

        50% {
          border-color: #ff9f43;
          box-shadow: 0 0 20px rgba(255, 215, 0, 0.5);
        }
      }

      @keyframes fairy-glow {

        0%,
        100% {
          box-shadow:
            0 0 15px var(--accent-gold),
            0 0 25px var(--accent-mana);
          filter: brightness(1);
        }

        50% {
          box-shadow:
            0 0 25px var(--accent-gold),
            0 0 40px #4da6ff;
          filter: brightness(1.15);
        }
      }

      @keyframes bellShake {
        0% {
          transform: rotate(0);
        }

        15% {
          transform: rotate(10deg);
        }

        30% {
          transform: rotate(-10deg);
        }

        45% {
          transform: rotate(5deg);
        }

        60% {
          transform: rotate(-5deg);
        }

        75% {
          transform: rotate(2deg);
        }

        90% {
          transform: rotate(-2deg);
        }

        100% {
          transform: rotate(0);
        }
      }

      @keyframes faction-pop {
        0% {
          opacity: 0;
          transform: scale(0.9);
        }

        100% {
          opacity: 1;
          transform: scale(1);
        }
      }

      @keyframes fadeIn {
        0% {
          opacity: 0;
        }

        100% {
          opacity: 1;
        }
      }

      @keyframes discard-fade {
        0% {
          opacity: 1;
          transform: scale(1);
        }

        100% {
          opacity: 0;
          transform: scale(0.85) translateY(8px);
        }
      }

      @keyframes dy-stream-caret-blink {

        0%,
        45% {
          opacity: 1;
        }

        46%,
        100% {
          opacity: 0;
        }
      }

      .terminal-container {
