      }

      .dy-update-attention::after {
        content: "";
        position: absolute;
        top: 3px;
        right: 3px;
        z-index: 5;
        width: 8px;
        height: 8px;
        border: 1px solid rgba(255, 255, 255, 0.28);
        border-radius: 50%;
        background: var(--accent-blood);
        box-shadow: 0 0 6px var(--accent-blood-glow);
        animation: dy-update-dot-pulse 1.8s ease-in-out infinite;
      }

      .time-display {
        font-size: 0.9em;
        color: var(--accent-gold);
        text-shadow: 0 0 5px var(--accent-gold-glow);
