        overflow: visible;
        border-color: var(--rare-text);
      }

      .dy-portrait-search-card .info-title {
        color: var(--rare-text);
      }

      .portrait-search-row {
        display: flex;
        gap: 8px;
      }

      .portrait-search-row .reply-input {
        flex: 1;
        box-sizing: border-box;
        height: 35px;
        padding: 5px 10px;
      }

      .portrait-search-row .reply-button {
        min-width: 60px;
        height: 35px;
        padding: 0 15px;
      }

      .dy-portrait-search-result {
        display: none;
        margin-top: 15px;
      }

      .dy-portrait-search-result.show {
        display: block;
      }

      .dy-search-result-card {
        margin-bottom: 10px;
        border-color: rgba(217, 128, 250, 0.5);
        background: rgba(0, 0, 0, 0.4);
      }

      .dy-search-result-card .info-title button {
        padding: 0;
        border: 0;
        background: none;
        color: var(--rare-text);
        font: inherit;
        cursor: pointer;
      }

      .dy-search-result-card .info-title span {
        color: var(--text-dim);
        font-size: 0.8em;
      }

      .dy-beauty-root {
        margin-top: 15px;
      }

      .portrait-actions {
        --portrait-action-size: clamp(30px, 6vw, 36px);
        display: grid;
        grid-template-columns: minmax(0, 1fr);
        grid-auto-columns: var(--portrait-action-size);
        grid-auto-flow: column;
        gap: 6px;
        align-items: stretch;
        padding: 2px 5px;
      }

      .portrait-toggle-btn {
        min-width: 0;
        background: linear-gradient(to right,
            transparent,
            rgba(255, 215, 0, 0.08),
            transparent);
        border: 1px dashed rgba(255, 215, 0, 0.3);
        color: var(--accent-gold);
        padding: 8px 0;
        text-align: center;
        border-radius: 4px;
        cursor: pointer;
        font-size: 0.9em;
        font-weight: bold;
        transition: all 0.3s;
        letter-spacing: 2px;
        min-height: var(--portrait-action-size);
        box-sizing: border-box;
      }

      .portrait-toggle-btn:hover {
        background: linear-gradient(to right, transparent, rgba(255, 215, 0, 0.15), transparent);
        box-shadow: 0 0 10px var(--accent-gold-glow);
      }

      .large-portrait {
        display: none;
        margin-top: 10px;
        width: 100%;
        border-radius: 8px;
        border: 1px solid rgba(255, 255, 255, 0.15);
        box-shadow:
          0 5px 15px rgba(0, 0, 0, 0.5),
          inset 0 0 20px rgba(0, 0, 0, 0.8);
        overflow: hidden;
        align-items: center;
        justify-content: center;
        background: rgba(5, 4, 6, 0.9);
      }

      .large-portrait.show {
        display: flex;
        animation: fadeIn 0.4s ease;
      }

      .large-portrait img {
        width: 100%;
        max-height: 500px;
        object-fit: contain;
        cursor: zoom-in;
        transition: filter 0.3s;
      }

      .large-portrait img:hover {
        filter: brightness(1.1);
      }

      .fairy-container {
        position: absolute;
        bottom: 5px;
        right: 20px;
        display: flex;
        align-items: flex-end;
        gap: 12px;
        z-index: 100;
        animation: fairy-bob 4s infinite ease-in-out;
        pointer-events: none;
      }

      .fairy-avatar {
        appearance: none;
        padding: 0;
        width: 45px;
        height: 45px;
        background-size: cover;
        background-position: center;
        border-radius: 50%;
        cursor: pointer;
        pointer-events: auto;
        box-shadow:
          0 0 20px var(--accent-gold),
          0 0 30px var(--accent-mana);
        transition:
          transform 0.3s,
          filter 0.3s;
        border: 2px solid #fff;
        animation: fairy-glow 3s infinite ease-in-out;
      }

      .fairy-avatar:hover {
        transform: scale(1.15) rotate(5deg);
        filter: brightness(1.2);
      }

      .fairy-bubble {
        max-width: 240px;
        background: rgba(20, 15, 25, 0.95);
        border: 1px solid var(--accent-gold);
        padding: 15px;
        border-radius: 12px;
        border-bottom-right-radius: 2px;
        font-size: 0.9em;
        color: var(--text-main);
        box-shadow: 0 5px 20px rgba(0, 0, 0, 0.5);
        position: relative;
        opacity: 0;
        transform: translateY(10px);
        transition:
          opacity 0.3s ease,
          transform 0.3s ease;
        backdrop-filter: blur(4px);
      }

      .image-modal-overlay {
        display: flex;
        position: fixed;
        z-index: 9999;
        left: 0;
        top: 0;
        width: 100%;
        height: 100%;
        overflow: auto;
        background-color: rgba(0, 0, 0, 0.9);
        justify-content: center;
        align-items: center;
        backdrop-filter: blur(5px);
      }

      .image-modal-content {
        margin: auto;
        display: block;
        max-width: 90%;
        max-height: 90vh;
        border-radius: 8px;
        box-shadow: 0 0 30px var(--accent-gold-glow);
        cursor: grab;
        touch-action: none;
        user-select: none;
        -webkit-user-drag: none;
        transition: transform 0.1s ease-out;
      }

      .image-modal-content:active {
        cursor: grabbing;
        transition: none;
      }

      .image-modal-close,
      .faction-modal-close,
      .luck-modal-close {
        appearance: none;
        width: auto;
        height: auto;
        padding: 0;
        border: 0;
        border-radius: 0;
        background: transparent;
        box-shadow: none;
        font-family: inherit;
      }

      .fairy-bubble.dy-fairy-visible {
        opacity: 1;
        transform: translateY(0);
        pointer-events: auto;
      }

      .image-modal-close {
        position: absolute;
        top: 15px;
        right: 35px;
        color: var(--text-main);
        font-size: 40px;
        font-weight: bold;
        transition: 0.3s;
        cursor: pointer;
        z-index: 10000;
      }

      .image-modal-close:hover,
      .image-modal-close:focus {
        color: var(--accent-blood);
        text-decoration: none;
      }

      .message-reply-container {
        margin-top: 10px;
        display: flex;
        gap: 10px;
        align-items: flex-end;
      }

      .reply-input {
        flex-grow: 1;
        background: rgba(0, 0, 0, 0.3);
        border: 1px solid var(--accent-mana);
        border-radius: 6px;
        padding: 10px;
        color: var(--text-main);
        font-family: inherit;
        font-size: 0.9em;
        resize: none;
        overflow-y: auto;
        max-height: 120px;
        line-height: 1.5;
      }

      .reply-input:focus {
        outline: none;
        border-color: var(--accent-gold);
        box-shadow:
          inset 0 0 5px rgba(0, 0, 0, 0.5),
          0 0 8px rgba(255, 215, 0, 0.2);
      }

      .reply-input::placeholder {
        color: var(--text-dim);
        opacity: 0.7;
      }

      .reply-input::-webkit-scrollbar {
        width: 4px;
      }

      .reply-input::-webkit-scrollbar-thumb {
        background: var(--accent-mana);
        border-radius: 2px;
      }

      .reply-button {
        background: linear-gradient(135deg, var(--accent-mana), #3480db);
        color: #fff;
        border: none;
        padding: 10px 18px;
        border-radius: 6px;
        cursor: pointer;
        font-weight: bold;
        transition: all 0.3s;
        box-shadow: 0 2px 5px rgba(0, 0, 0, 0.3);
        height: 42px;
        white-space: nowrap;
        min-width: 140px;
        flex-shrink: 0;
        text-align: center;
      }

      .reply-button:hover {
        transform: translateY(-1px);
        box-shadow: 0 4px 8px rgba(77, 166, 255, 0.3);
      }

      .reply-button:disabled {
        background: #555;
        cursor: not-allowed;
        opacity: 0.6;
      }

      .map-section-title {
        color: var(--accent-gold);
        text-align: center;
        margin: 25px 0 15px;
        font-size: 1.25em;
        letter-spacing: 3px;
        font-weight: 800;
        text-shadow:
          0 0 10px var(--accent-gold-glow),
          0 0 20px rgba(255, 215, 0, 0.2);
        border-bottom: 2px solid transparent;
        border-image: linear-gradient(90deg,
            transparent,
            var(--accent-gold),
            transparent) 1;
        padding-bottom: 8px;
        transition: transform 0.2s;
      }

      .map-section-title:hover {
        transform: scale(1.02);
      }

      .map-section-title-xian {
        color: var(--rare-text);
        text-shadow:
          0 0 10px rgba(217, 128, 250, 0.5),
          0 0 20px rgba(217, 128, 250, 0.2);
        border-image: linear-gradient(90deg,
            transparent,
            var(--rare-text),
            transparent) 1;
      }

      .map-wrapper {
        width: 100%;
        height: 380px;
        position: relative;
        background:
          radial-gradient(circle at 50% 50%,
            rgba(30, 35, 45, 0.7),
            rgba(5, 5, 8, 0.9)),
          repeating-linear-gradient(0deg,
            transparent,
            transparent 39px,
            rgba(255, 255, 255, 0.03) 39px,
            rgba(255, 255, 255, 0.03) 40px),
          repeating-linear-gradient(90deg,
            transparent,
            transparent 39px,
            rgba(255, 255, 255, 0.03) 39px,
            rgba(255, 255, 255, 0.03) 40px);
        border: 1px solid var(--border-metal);
        border-radius: 12px;
        box-shadow:
          inset 0 0 40px rgba(0, 0, 0, 0.8),
          0 5px 15px rgba(0, 0, 0, 0.5);
        overflow: hidden;
        user-select: none;
        margin-bottom: 25px;
        transition: box-shadow 0.3s ease;
      }

      .map-wrapper:hover {
        box-shadow:
          inset 0 0 60px rgba(0, 0, 0, 0.9),
          0 8px 25px rgba(0, 0, 0, 0.7);
      }

      .map-grid {
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        pointer-events: none;
      }

      .map-node {
        appearance: none;
        padding: 0;
        position: absolute;
        width: 22px;
        height: 22px;
        border-radius: 50%;
        transform: translate(-50%, -50%);
        cursor: pointer;
        transition: all 0.35s cubic-bezier(0.34, 1.56, 0.64, 1);
        z-index: 10;
        display: flex;
        align-items: center;
        justify-content: center;
        border: 2px solid rgba(255, 255, 255, 0.8);
      }

      .map-node::before {
        content: "";
        position: absolute;
        width: 100%;
        height: 100%;
        border-radius: 50%;
        opacity: 0.3;
        background: currentColor;
      }

      .map-node::after {
        content: "";
        position: absolute;
        width: 160%;
        height: 160%;
        border-radius: 50%;
        border: 1px dashed rgba(255, 255, 255, 0.3);
        pointer-events: none;
        opacity: 0.5;
      }

      .map-node:hover,
      .map-node.active-node {
        transform: translate(-50%, -50%) scale(1.4);
        z-index: 25;
        border-color: #fff;
        box-shadow: 0 0 25px currentColor;
      }

      .map-node.active-node::after {
        border: 2px solid currentColor;
        border-style: dotted;
        opacity: 1;
      }

      .map-node-label {
        position: absolute;
        top: 30px;
        white-space: nowrap;
        font-size: 0.85em;
        text-shadow: 0 2px 4px #000;
        color: var(--text-main);
        pointer-events: none;
        transition: all 0.3s ease;
        padding: 4px 10px;
        border-radius: 4px;
        background: rgba(20, 20, 25, 0.75);
        backdrop-filter: blur(4px);
        border: 1px solid rgba(255, 255, 255, 0.1);
        opacity: 0.85;
        transform: translateY(0);
      }

      .map-node:hover .map-node-label,
      .map-node.active-node .map-node-label {
        opacity: 1;
        transform: translateY(3px) scale(1.1);
        background: rgba(20, 20, 25, 0.95);
        z-index: 30;
      }

      .node-center {
        background: var(--accent-gold);
        color: var(--accent-gold);
        box-shadow: 0 0 15px var(--accent-gold);
      }

      .node-center .map-node-label {
        border-color: rgba(255, 215, 0, 0.5);
        color: var(--accent-gold);
      }

      .node-east {
        background: var(--accent-san);
        color: var(--accent-san);
        box-shadow: 0 0 15px var(--accent-san);
      }

      .node-east .map-node-label {
        border-color: rgba(46, 204, 113, 0.5);
        color: var(--accent-san);
      }

      .node-south {
        background: var(--accent-blood);
        color: var(--accent-blood);
        box-shadow: 0 0 15px var(--accent-blood);
      }

      .node-south .map-node-label {
        border-color: rgba(255, 77, 77, 0.5);
        color: var(--accent-blood);
      }

      .node-west {
        background: #eccc68;
        color: #eccc68;
        box-shadow: 0 0 15px #eccc68;
      }

      .node-west .map-node-label {
        border-color: rgba(236, 204, 104, 0.5);
        color: #eccc68;
      }

      .node-north {
        background: var(--accent-mana);
        color: var(--accent-mana);
        box-shadow: 0 0 15px var(--accent-mana);
      }

      .node-north .map-node-label {
        border-color: rgba(77, 166, 255, 0.5);
        color: var(--accent-mana);
      }

      .node-special {
        background: var(--rare-text);
        color: var(--rare-text);
        box-shadow: 0 0 15px var(--rare-text);
        width: 14px;
        height: 14px;
      }

      .node-special .map-node-label {
        border-color: rgba(217, 128, 250, 0.5);
        color: var(--rare-text);
        font-size: 0.75em;
        top: 22px;
      }

      .map-line {
        position: absolute;
        height: 2px;
        background: rgba(255, 255, 255, 0.15);
        transform-origin: left center;
        pointer-events: none;
        z-index: 1;
      }

      .map-node.label-right .map-node-label {
        top: 50%;
        left: auto;
        right: -10px;
        transform: translate(100%, -50%);
      }

      .map-node.label-right:hover .map-node-label,
      .map-node.label-right.active-node .map-node-label {
        transform: translate(100%, -50%) scale(1.1);
        margin-left: 3px;
      }

      .anim-shake .dy-btn-icon {
        display: inline-block;
        animation: bellShake 1.5s infinite ease-in-out;
        transform-origin: top center;
      }

      .location-detail-panel {
        border-top: 2px solid rgba(255, 255, 255, 0.1);
        padding-top: 20px;
        display: none;
        margin-top: 15px;
      }

      .location-detail-panel.active {
        display: block;
        animation: mapPanelSlideUp 0.4s cubic-bezier(0.2, 0.8, 0.2, 1);
      }

      .location-detail-panel .info-card {
        transition:
          border-color 0.3s,
          box-shadow 0.3s;
        border-left-width: 4px;
      }

      .faction-tag {
        appearance: none;
        display: inline-block;
        padding: 2px 8px;
        border-radius: 4px;
        font-size: 0.8em;
        margin-right: 5px;
        margin-bottom: 5px;
        border: 1px solid;
        cursor: pointer;
        transition:
          transform 0.2s,
          box-shadow 0.2s;
      }

      .faction-tag:hover {
        transform: scale(1.05);
        box-shadow: 0 2px 6px rgba(0, 0, 0, 0.5);
      }

      .tag-human {
        border-color: var(--accent-gold);
        color: var(--accent-gold);
        background: rgba(255, 215, 0, 0.1);
      }

      .tag-demon {
        border-color: var(--accent-blood);
        color: var(--accent-blood);
        background: rgba(255, 77, 77, 0.1);
      }

      .tag-monster {
        border-color: var(--accent-san);
        color: var(--accent-san);
        background: rgba(46, 204, 113, 0.1);
      }

      .tag-neutral {
        border-color: var(--accent-mana);
        color: var(--accent-mana);
        background: rgba(77, 166, 255, 0.1);
      }

      /* 修复配置页与动画 */
      .faction-modal-overlay {
        display: flex;
        position: fixed;
        inset: 0;
        z-index: 10000;
        width: auto;
        height: auto;
        padding: 16px;
        overflow: hidden;
        background-color: rgba(0, 0, 0, 0.7);
        backdrop-filter: blur(4px);
        justify-content: center;
        align-items: center;
        box-sizing: border-box;
      }

      .faction-modal-content {
        background: linear-gradient(145deg,
            rgba(25, 20, 30, 0.95),
            rgba(15, 10, 15, 0.98));
        border: 1px solid var(--border-metal);
        border-top: 2px solid var(--accent-gold);
        border-bottom: 2px solid var(--accent-gold);
        border-radius: 8px;
        display: flex;
        flex-direction: column;
        width: min(92%, 470px);
        max-width: 470px;
        max-height: calc(100vh - 32px);
        max-height: calc(100dvh - 32px);
        padding: 25px;
        overflow: hidden;
        box-shadow:
          0 0 40px rgba(0, 0, 0, 0.9),
          inset 0 0 20px rgba(255, 215, 0, 0.05);
        position: relative;
        animation: faction-pop 0.4s cubic-bezier(0.2, 0.8, 0.2, 1.1);
        text-align: center;
        box-sizing: border-box;
      }

      .faction-modal-close {
        position: absolute;
        top: 8px;
        right: 15px;
        color: var(--text-dim);
        font-size: 28px;
        cursor: pointer;
        transition: 0.3s;
        line-height: 1;
      }

      .faction-modal-close:hover {
        color: var(--accent-blood);
        transform: scale(1.1) rotate(90deg);
      }

      .faction-modal-header {
        font-size: 1.3em;
        font-weight: bold;
        color: var(--accent-gold);
        margin-bottom: 15px;
        padding-bottom: 12px;
        border-bottom: 1px dashed rgba(255, 255, 255, 0.1);
        text-shadow: 0 0 8px var(--accent-gold-glow);
        letter-spacing: 2px;
      }

      .faction-modal-body {
        min-height: 0;
        overflow-y: auto;
        overscroll-behavior: contain;
        font-size: 1.05em;
        color: var(--text-main);
        line-height: 1.6;
        margin-bottom: 15px;
        padding-right: 5px;
        scrollbar-width: none;
        -ms-overflow-style: none;
      }

      .faction-modal-body::-webkit-scrollbar {
        display: none;
        width: 0;
        height: 0;
      }

      .faction-modal-content--lore {
        width: min(94vw, 680px);
        max-width: 680px;
      }

      .faction-lore-toolbar {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 10px;
        margin: -3px 0 12px;
        color: var(--text-dim);
        font-size: 0.72em;
        text-align: left;
      }

      .faction-lore-toolbar button {
        flex: 0 0 auto;
        padding: 5px 10px;
        border: 1px solid rgba(100, 180, 255, 0.38);
        border-radius: 999px;
        background: rgba(100, 180, 255, 0.08);
        color: var(--accent-mana);
        font: inherit;
        cursor: pointer;
      }

      .faction-modal-body--lore {
        padding-right: 0;
        text-align: left;
      }

      .faction-lore-blocks {
        display: grid;
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 8px;
      }

      .faction-lore-heading {
        grid-column: 1 / -1;
        margin-top: 5px;
        padding: 7px 10px;
        border-left: 3px solid var(--accent-gold);
        background: linear-gradient(90deg, rgba(255, 215, 0, 0.1), transparent);
        color: var(--accent-gold);
        font-weight: 700;
        letter-spacing: 1px;
      }

      .faction-lore-field {
        min-width: 0;
        padding: 9px 10px;
        border: 1px solid rgba(255, 255, 255, 0.08);
        border-radius: 7px;
        background: rgba(0, 0, 0, 0.2);
        box-sizing: border-box;
      }

      .faction-lore-field.is-long {
        grid-column: 1 / -1;
      }

      .faction-lore-field strong {
        display: block;
        margin-bottom: 4px;
        color: var(--rare-text);
        font-size: 0.78em;
        letter-spacing: 0.04em;
      }

      .faction-lore-field p,
      .faction-lore-raw {
        margin: 0;
        color: var(--text-main);
        line-height: 1.75;
        overflow-wrap: anywhere;
        white-space: pre-wrap;
      }

      .faction-lore-text {
        grid-column: 1 / -1;
        margin: 0;
        padding: 7px 5px;
        color: var(--text-main);
        line-height: 1.75;
        overflow-wrap: anywhere;
        white-space: pre-wrap;
      }

      .faction-lore-field p {
        font-size: 0.88em;
      }

      .faction-lore-raw {
        text-align: left;
      }

      @media (max-width: 600px) {
        .faction-modal-content--lore {
          width: calc(100vw - 16px);
          padding: 17px 13px;
        }

        .faction-lore-toolbar {
          align-items: flex-start;
          font-size: 0.68em;
        }

        .faction-lore-blocks {
          grid-template-columns: 1fr;
        }

        .faction-lore-field,
        .faction-lore-field.is-long {
          grid-column: 1;
        }
      }

      .faction-modal-map {
        display: block;
        margin: 15px 0;
        padding-top: 14px;
        border-top: 1px dashed rgba(255, 255, 255, 0.12);
      }

      .faction-map-title {
        margin-bottom: 8px;
        color: var(--accent-mana);
        font-size: 0.85em;
        letter-spacing: 2px;
      }

      .faction-map-image {
        display: block;
        max-width: 100%;
        max-height: 260px;
        margin: 0 auto;
        border: 1px solid rgba(255, 255, 255, 0.14);
        border-radius: 6px;
        box-shadow: 0 4px 14px rgba(0, 0, 0, 0.55);
        cursor: zoom-in;
        object-fit: contain;
      }

      .faction-modal-footer {
        font-size: 0.75em;
        color: var(--rare-text);
        opacity: 0.8;
        letter-spacing: 4px;
        margin-top: 10px;
      }

      .luck-modal-overlay {
        display: none;
        position: fixed;
        z-index: 99999;
        left: 0;
        top: 0;
        width: 100%;
