        border: 1px solid rgba(46, 204, 113, 0.4);
        color: #e0f0ff;
        border-top-right-radius: 0;
      }

      .wx-msg-actions {
        display: none;
        gap: 10px;
        margin-top: 4px;
        font-size: 0.75em;
        opacity: 0.8;
        justify-content: flex-end;
      }

      .wx-msg-left .wx-msg-actions {
        justify-content: flex-start;
      }

      .wx-msg-row:hover .wx-msg-actions {
        display: flex;
      }

      .wx-msg-action-btn {
        cursor: pointer;
        color: var(--text-dim);
        transition: color 0.2s;
        background: rgba(0, 0, 0, 0.3);
        padding: 2px 6px;
        border-radius: 4px;
        border: 1px solid rgba(255, 255, 255, 0.1);
      }

      .wx-msg-action-btn:hover {
        color: var(--accent-gold);
        border-color: var(--accent-gold);
        background: rgba(255, 215, 0, 0.1);
      }

      .wx-chat-input-area {
        position: relative;
        z-index: 105;
        padding: 12px;
        background: rgba(10, 10, 15, 0.9);
        border-top: 1px solid rgba(255, 255, 255, 0.1);
        flex-shrink: 0;
      }

      .wx-detail-modal {
        display: none;
        position: absolute;
        top: 45px;
        left: 50%;
        transform: translateX(-50%);
        background: linear-gradient(145deg,
            rgba(25, 25, 30, 0.95),
            rgba(15, 15, 20, 0.98));
        border: 1px solid var(--accent-mana);
        border-radius: 8px;
        padding: 15px;
        z-index: 100;
        box-shadow:
          0 5px 20px rgba(0, 0, 0, 0.6),
          inset 0 0 10px rgba(77, 166, 255, 0.1);
        width: 200px;
        text-align: center;
        backdrop-filter: blur(5px);
        animation: fadeIn 0.2s ease;
      }

      .wx-detail-modal.show {
        display: block;
      }

      .wx-detail-item {
        margin: 10px 0;
        font-size: 0.95em;
        display: flex;
        justify-content: space-between;
        border-bottom: 1px dashed rgba(255, 255, 255, 0.1);
        padding-bottom: 6px;
      }

      .wx-detail-item:last-child {
        border-bottom: none;
        margin-bottom: 0;
      }

      @media (max-width: 700px) {
        .terminal-container {
          border-radius: 0;
          border: none;
          border-top: 2px solid var(--border-metal);
          border-bottom: 2px solid var(--border-metal);
        }

        .content-grid {
          grid-template-columns: minmax(0, 1fr);
        }

        .main-panel,
        .tab-content,
        .info-card {
          min-width: 0;
          max-width: 100%;
        }

        .portrait-search-row {
          min-width: 0;
        }

        .portrait-search-row .reply-input {
          min-width: 50px;
          flex: 1 1 0;
        }

        .status-panel {
          flex-direction: row;
          padding: 15px;
          gap: 20px;
          flex-wrap: wrap;
          justify-content: center;
          background-color: rgba(20, 18, 22, 0.8);
          border-right: none;
          border-bottom: 1px solid rgba(255, 255, 255, 0.1);
        }

        .avatar-frame {
          width: 70px;
          height: 70px;
        }

        .stat-group {
          flex: 1;
          min-width: 200px;
        }

        .rank-tag {
          margin-top: -5px;
        }

        .tab-content {
          max-height: 350px;
          padding: 15px;
        }

        #tab-messages {
          padding: 10px;
          height: 350px;
        }

        .wx-chat-input-area {
          padding: 8px;
        }

        .message-reply-container {
          gap: 6px;
        }

        .reply-button {
          min-width: 80px;
          padding: 8px 12px;
        }

        .fairy-container {
          right: 10px;
          bottom: 10px;
        }

        .fairy-bubble {
          max-width: 180px;
          font-size: 0.85em;
          padding: 10px;
        }

        .wx-msg-actions {
          display: flex;
          flex-wrap: wrap;
        }
      }

      /* Vue notice actions preserve the original three distinct actions in one row. */
      .dy-notice-footer {
        width: 100%;
      }

      .dy-notice-footer>small {
        width: 100%;
        color: var(--text-dim);
        text-align: center;
      }

      .dy-notice-actions {
        display: grid;
        grid-template-columns: repeat(3, minmax(0, 1fr));
        width: 100%;
        gap: 8px;
      }

      .dy-notice-footer .dy-notice-action {
        position: relative;
        isolation: isolate;
        overflow: hidden;
        display: flex;
        align-items: center;
        justify-content: center;
        min-width: 0;
        min-height: 42px;
        padding: 8px 9px;
        border-radius: 8px;
        line-height: 1.35;
        text-align: center;
        box-sizing: border-box;
        transition:
          transform 0.16s ease,
          filter 0.16s ease,
          box-shadow 0.2s ease,
          border-color 0.2s ease;
        will-change: transform;
      }

      .dy-notice-footer .dy-notice-action::before {
        content: "";
        position: absolute;
        z-index: -1;
        inset: -45% auto -45% -35%;
        width: 28%;
        opacity: 0;
        transform: skewX(-20deg) translateX(-220%);
        background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.42), transparent);
        pointer-events: none;
      }

      .dy-notice-footer .dy-notice-action:hover,
      .dy-notice-footer .dy-notice-action:focus-visible {
        transform: translateY(-2px);
        filter: brightness(1.14);
      }

      .dy-notice-footer .dy-notice-action:active {
        transform: translateY(1px) scale(0.965);
        filter: brightness(1.24);
      }

      .dy-notice-footer .dy-notice-action.is-activating {
        animation: dy-notice-action-press 0.42s cubic-bezier(0.2, 0.82, 0.22, 1) !important;
      }

      .dy-notice-footer .dy-notice-action.is-activating::before {
        animation: dy-notice-action-sheen 0.42s ease-out;
      }

      .dy-notice-footer .dy-notice-action--version {
        border-color: rgba(255, 215, 0, 0.48);
        background: rgba(255, 215, 0, 0.1);
        color: var(--accent-gold);
      }

      .dy-notice-footer .dy-notice-action--version:hover,
      .dy-notice-footer .dy-notice-action--version:focus-visible {
        box-shadow: 0 7px 18px rgba(255, 215, 0, 0.2);
      }

      .dy-notice-footer .dy-notice-action--wiki {
        border-color: color-mix(in srgb, var(--rare-text) 52%, transparent);
        background: color-mix(in srgb, var(--rare-text) 12%, transparent);
        color: var(--rare-text);
      }

      .dy-notice-footer .dy-notice-action--wiki:hover,
      .dy-notice-footer .dy-notice-action--wiki:focus-visible {
        box-shadow: 0 7px 18px color-mix(in srgb, var(--rare-text) 22%, transparent);
      }

      .dy-notice-footer .dy-notice-action--sync {
        border-color: rgba(100, 180, 255, 0.5);
        background: rgba(100, 180, 255, 0.1);
        color: var(--accent-mana, #64b4ff);
      }

      .dy-notice-footer .dy-notice-action--sync:hover,
      .dy-notice-footer .dy-notice-action--sync:focus-visible {
        box-shadow: 0 7px 18px rgba(100, 180, 255, 0.2);
      }

      @keyframes dy-notice-action-press {
        0% {
          transform: translateY(0) scale(1);
        }

        42% {
          transform: translateY(1px) scale(0.95);
        }

        72% {
          transform: translateY(-2px) scale(1.025);
        }

        100% {
          transform: translateY(0) scale(1);
        }
      }

      @keyframes dy-notice-action-sheen {
        0% {
          opacity: 0;
          transform: skewX(-20deg) translateX(-220%);
        }

        22% {
          opacity: 0.82;
        }

        100% {
          opacity: 0;
          transform: skewX(-20deg) translateX(620%);
        }
      }

      @media (prefers-reduced-motion: reduce) {

        .dy-notice-footer .dy-notice-action,
        .dy-notice-footer .dy-notice-action::before {
          animation-duration: 0.01ms !important;
          transition-duration: 0.01ms !important;
        }
      }

      .dy-portrait-search-results--inline {
        max-height: none;
        overflow: visible;
      }

      /* Portrait editor and missing-resource prompt follow the active status-bar theme. */
      .portrait-custom-modal,
      .dy-missing-portrait-overlay {
        position: fixed;
        inset: 0;
        z-index: 100000;
        display: flex;
        align-items: center;
        justify-content: center;
        padding: 18px;
        background: rgba(0, 0, 0, 0.82);
        backdrop-filter: blur(5px);
        box-sizing: border-box;
      }

      .portrait-custom-dialog,
      .dy-missing-portrait-dialog {
        position: relative;
        width: min(100%, 540px);
        max-height: 88vh;
        overflow-y: auto;
        padding: 24px;
        border: 1px solid var(--border-metal);
        border-top: 2px solid var(--accent-gold);
        border-bottom: 2px solid var(--accent-gold);
        border-radius: 12px;
        background: linear-gradient(145deg, rgba(25, 20, 30, 0.98), rgba(15, 10, 15, 0.99));
        box-shadow: 0 0 40px rgba(0, 0, 0, 0.9), inset 0 0 20px rgba(255, 215, 0, 0.05);
        color: var(--text-main);
        box-sizing: border-box;
      }

      .portrait-custom-dialog h3,
      .dy-missing-portrait-dialog h3 {
        margin: 0 0 16px;
        padding: 0 78px 12px;
        border-bottom: 1px dashed rgba(255, 255, 255, 0.12);
        color: var(--accent-gold);
        font-size: 1.12em;
        letter-spacing: 2px;
        text-align: center;
        text-shadow: 0 0 8px var(--accent-gold-glow);
      }

      .portrait-custom-dialog .btn-rst-all {
        position: absolute;
        top: 13px;
        right: 13px;
        z-index: 2;
        padding: 5px 8px;
        border: 1px solid var(--accent-blood);
        border-radius: 5px;
        background: rgba(255, 77, 77, 0.12);
        color: var(--accent-blood);
        font: inherit;
        font-size: 0.72em;
        cursor: pointer;
      }

      .portrait-preview-wrapper.dy-preview-visible {
        display: flex;
        align-items: center;
        justify-content: center;
        width: 100%;
        min-height: 120px;
        max-height: 240px;
        margin-bottom: 14px;
        overflow: hidden;
        border: 1px solid var(--border-metal);
        border-radius: 8px;
        background: rgba(0, 0, 0, 0.55);
        box-shadow: inset 0 0 18px rgba(0, 0, 0, 0.75), 0 0 12px var(--accent-gold-glow);
      }

      .portrait-preview-wrapper .portrait-preview {
        display: block;
        width: auto;
        max-width: 100%;
        max-height: 238px;
        margin: 0;
        border: 0;
        object-fit: contain;
      }

      .portrait-file-row {
        display: grid;
        grid-template-columns: auto minmax(0, 1fr);
        align-items: stretch;
        gap: 8px;
        margin-bottom: 14px;
      }

      .portrait-custom-dialog .portrait-file-label {
        display: flex;
        align-items: center;
        margin: 0;
        padding: 8px 14px;
        border-color: var(--accent-gold);
        background: rgba(255, 215, 0, 0.06);
        color: var(--accent-gold);
      }

      .portrait-file-name {
        display: flex;
        align-items: center;
        min-width: 0;
        padding: 0 10px;
        overflow: hidden;
        border: 1px solid rgba(255, 255, 255, 0.12);
        border-radius: 6px;
        background: rgba(0, 0, 0, 0.4);
        color: var(--text-dim);
        font-size: 0.8em;
        text-overflow: ellipsis;
        white-space: nowrap;
      }

      .portrait-file-name.selected {
        color: var(--accent-health, #64ff8a);
      }

      .portrait-custom-dialog .portrait-url-label {
        margin-bottom: 7px;
        color: var(--text-dim);
      }

      .portrait-url-list {
        display: grid;
        gap: 8px;
      }

      .portrait-custom-dialog .url-input-row {
        display: grid;
        grid-template-columns: minmax(0, 1fr) auto;
        gap: 8px;
        margin: 0;
      }

      .portrait-custom-dialog .url-input-row input {
        min-width: 0;
        margin: 0;
        border-color: rgba(255, 215, 0, 0.32);
        background: rgba(0, 0, 0, 0.5);
        color: var(--text-main);
      }

      .portrait-custom-dialog .url-input-row input:focus {
        border-color: var(--accent-gold);
        box-shadow: 0 0 9px var(--accent-gold-glow);
      }

      .portrait-custom-dialog .btn-remove-url {
        width: 38px;
        border: 1px solid rgba(255, 77, 77, 0.4);
        border-radius: 6px;
        background: rgba(255, 77, 77, 0.1);
        color: var(--accent-blood);
        cursor: pointer;
      }

      .portrait-custom-dialog .btn-add-url {
        width: 100%;
        margin: 10px 0 0;
        padding: 8px;
        border: 1px dashed rgba(100, 180, 255, 0.5);
        border-radius: 6px;
        background: rgba(100, 180, 255, 0.08);
        color: var(--accent-mana, #64b4ff);
        font: inherit;
        cursor: pointer;
      }

      .portrait-custom-dialog .portrait-custom-hint {
        margin: 9px 0 12px;
        color: var(--text-dim);
      }

      .portrait-custom-error {
        margin: 0 0 10px;
        text-align: center;
      }

      .portrait-custom-dialog .btn-row {
        display: grid;
        grid-template-columns: repeat(3, minmax(0, 1fr));
        gap: 9px;
        margin-top: 0;
      }

      .portrait-custom-dialog .btn-row button {
        min-width: 0;
        padding: 9px 8px;
      }

      .portrait-reset-confirm {
        position: absolute;
        inset: 0;
        z-index: 5;
        display: flex;
        align-items: center;
        justify-content: center;
        padding: 18px;
        border-radius: inherit;
        background: rgba(0, 0, 0, 0.86);
        backdrop-filter: blur(3px);
      }

      .portrait-reset-confirm-card {
        width: min(100%, 350px);
        padding: 20px;
        border: 1px solid var(--accent-blood);
        border-radius: 10px;
        background: var(--bg-dark);
        box-shadow: 0 0 24px rgba(255, 77, 77, 0.26);
        text-align: center;
        box-sizing: border-box;
      }

      .portrait-reset-confirm-card h4 {
        margin: 0 0 12px;
        color: var(--accent-blood);
      }

      .portrait-reset-confirm-card p {
        color: var(--text-main);
        line-height: 1.6;
      }

      .portrait-reset-confirm-card>div {
        display: grid;
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 10px;
      }

      .portrait-reset-confirm-card button {
        padding: 8px;
        border: 1px solid rgba(255, 255, 255, 0.22);
        border-radius: 6px;
        background: rgba(255, 255, 255, 0.08);
        color: var(--text-main);
        cursor: pointer;
      }

      .portrait-reset-confirm-card button.danger {
        border-color: var(--accent-blood);
        background: var(--accent-blood);
        color: #fff;
      }

      .dy-missing-portrait-dialog {
        width: min(100%, 430px);
        text-align: center;
      }

      .dy-missing-portrait-icon {
        margin-bottom: 8px;
        font-size: 32px;
        text-shadow: 0 0 12px var(--accent-gold-glow);
      }

      .dy-missing-portrait-dialog h3 {
        padding-inline: 0;
      }

      .dy-missing-portrait-dialog p {
        margin: 0 0 8px;
        line-height: 1.65;
      }

      .dy-missing-portrait-dialog strong {
        color: var(--accent-mana, #64b4ff);
      }

      .dy-missing-portrait-hint {
        color: var(--text-dim);
        font-size: 0.9em;
      }

      .dy-missing-portrait-actions {
        display: grid;
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 9px;
        margin-top: 18px;
      }

      .dy-missing-portrait-actions button {
        min-width: 0;
        padding: 9px 10px;
        border-radius: 7px;
        font: inherit;
        font-weight: 700;
        cursor: pointer;
      }

      .dy-missing-portrait-custom {
        border: 1px solid rgba(255, 255, 255, 0.35);
        background: linear-gradient(135deg, #b8860b, #ffd700);
        color: #1a0f0f;
      }

      .dy-missing-portrait-notice {
        border: 1px solid rgba(100, 180, 255, 0.45);
        background: rgba(100, 180, 255, 0.12);
        color: var(--accent-mana, #64b4ff);
      }

      .dy-missing-portrait-cancel {
        grid-column: 1 / -1;
        justify-self: center;
        border: 1px solid rgba(255, 255, 255, 0.2);
        background: rgba(255, 255, 255, 0.05);
        color: var(--text-dim);
      }

      @media (max-width: 600px) {
        .dy-notice-actions {
          gap: 5px;
        }

        .dy-notice-footer .dy-notice-action {
          padding: 7px 5px;
          font-size: 0.76em;
        }

        .portrait-custom-modal,
        .dy-missing-portrait-overlay {
          padding: 8px;
        }

        .portrait-custom-dialog,
        .dy-missing-portrait-dialog {
          padding: 18px 14px;
        }

        .portrait-custom-dialog h3 {
          padding-inline: 62px;
          font-size: 1em;
        }

        .portrait-file-row {
          grid-template-columns: 1fr;
        }

        .portrait-file-name {
          min-height: 34px;
        }

        .portrait-custom-dialog .btn-row {
          grid-template-columns: 1fr;
        }
      }

      /* Phase 3 Vue overlays reuse the active theme variables. */
      .dy-notice-overlay,
      .jiuqi-overlay,
      .dy-portrait-search-overlay,
      .dy-jade-settings-overlay {
        position: fixed;
        inset: 0;
        z-index: 99999;
        display: flex;
        align-items: center;
        justify-content: center;
        padding: 18px;
        background: rgba(0, 0, 0, 0.82);
        backdrop-filter: blur(5px);
        box-sizing: border-box;
      }

      .dy-notice-dialog,
      .jiuqi-story-dialog,
      .jiuqi-edit-dialog,
      .dy-portrait-search-dialog {
        position: relative;
        width: min(100%, 480px);
        max-height: 88vh;
        overflow: hidden;
        padding: 22px;
        border: 1px solid var(--accent-gold);
        border-radius: 12px;
        background: linear-gradient(145deg, rgba(25, 20, 30, 0.98), rgba(15, 10, 15, 0.99));
        box-shadow: 0 0 36px rgba(255, 215, 0, 0.2);
        box-sizing: border-box;
      }

      .dy-notice-dialog h2,
      .jiuqi-story-dialog h2,
      .jiuqi-edit-dialog h2,
      .dy-portrait-search-dialog h2 {
        margin: 0 0 16px;
        color: var(--accent-gold);
        text-align: center;
        font-size: 1.25em;
        letter-spacing: 2px;
      }

      .dy-notice-tabs {
        display: grid;
        grid-auto-flow: column;
        grid-auto-columns: minmax(0, 1fr);
        border-bottom: 1px solid rgba(255, 255, 255, 0.12);
      }

      .dy-notice-tabs button {
        padding: 9px 4px;
        border: 0;
        border-bottom: 2px solid transparent;
        background: transparent;
        color: var(--text-dim);
        cursor: pointer;
      }

      .dy-notice-tabs button.active {
        border-bottom-color: var(--accent-gold);
        color: var(--accent-gold);
        font-weight: 700;
      }

      .dy-notice-content {
        min-height: 150px;
        max-height: 38vh;
        overflow-y: auto;
        padding: 14px 5px;
      }

      .dy-notice-text {
        margin: 0;
        color: var(--text-main);
        line-height: 1.7;
      }

      .dy-notice-text :first-child {
        margin-top: 0;
      }

      .dy-notice-text :last-child {
        margin-bottom: 0;
      }

      .dy-notice-text a {
        color: var(--accent-mana);
        text-decoration-color: rgba(77, 166, 255, 0.55);
        text-underline-offset: 3px;
      }

      .dy-notice-text blockquote {
        margin: 10px 0;
        padding: 7px 11px;
        border-left: 3px solid var(--accent-gold);
        background: rgba(255, 215, 0, 0.06);
      }

      .dy-notice-text pre,
      .dy-notice-text code {
        white-space: pre-wrap;
        overflow-wrap: anywhere;
      }

      .dy-notice-footer .dy-notice-action.dy-update-attention::after {
        display: none;
      }

      .dy-notice-update-dot {
        position: absolute;
        top: 4px;
        right: 4px;
        z-index: 5;
        width: 9px;
        height: 9px;
        border: 1px solid rgba(255, 255, 255, 0.32);
        border-radius: 50%;
        background: var(--accent-blood);
        box-shadow: 0 0 7px var(--accent-blood-glow);
        animation: dy-update-dot-pulse 1.8s ease-in-out infinite;
        pointer-events: none;
      }

      .dy-notice-text img {
        display: block;
        width: auto;
        max-width: 100%;
        height: auto;
        margin: 10px auto;
        border-radius: 8px;
        box-sizing: border-box;
      }

      .dy-notice-text table {
        width: 100%;
        border-collapse: collapse;
      }

      .dy-notice-text th,
      .dy-notice-text td {
        padding: 6px 8px;
        border: 1px solid rgba(255, 255, 255, 0.14);
      }

      .dy-notice-footer {
        display: grid;
        gap: 9px;
        justify-items: center;
        padding-top: 12px;
        border-top: 1px dashed rgba(255, 255, 255, 0.12);
      }

      .dy-notice-footer button,
      .dy-notice-footer a,
      .jiuqi-story-dialog>button,
      .jiuqi-edit-actions button {
        padding: 8px 16px;
        border: 1px solid rgba(255, 215, 0, 0.35);
        border-radius: 20px;
        background: rgba(255, 215, 0, 0.08);
        color: var(--accent-gold);
        font: inherit;
        text-decoration: none;
        cursor: pointer;
      }

      .jiuqi-story-dialog,
      .jiuqi-edit-dialog {
        border-color: var(--rare-text);
        box-shadow: 0 0 44px rgba(217, 128, 250, 0.3);
      }

      .jiuqi-story-dialog h2,
      .jiuqi-edit-dialog h2 {
        color: var(--rare-text);
      }

      .jiuqi-story-scroll {
        max-height: 52vh;
        overflow-y: auto;
        padding-right: 10px;
        color: var(--text-main);
        line-height: 1.8;
      }

      .jiuqi-story-scroll strong {
        color: var(--rare-text);
      }

      .jiuqi-story-scroll img {
        display: block;
        max-width: 100%;
        margin: 18px auto 0;
